DO $$
DECLARE
  rec RECORD;
  cur_status INT;
  cur_driver INT;
BEGIN
  FOR rec IN SELECT * FROM route_events ORDER BY event_id LOOP
    SELECT compliance_status, last_updated_by INTO cur_status, cur_driver
    FROM delivery_routes
    WHERE route_id = rec.route_id;

    IF rec.event_type = 1 AND cur_status = 0 THEN
      UPDATE delivery_routes
      SET compliance_status = 1, last_updated_by = rec.driver_id
      WHERE route_id = rec.route_id;
    ELSIF rec.event_type = 2 AND cur_status = 1 AND cur_driver = rec.driver_id THEN
      UPDATE delivery_routes
      SET compliance_status = 2
      WHERE route_id = rec.route_id;
    ELSIF rec.event_type = 3 AND (cur_status = 1 OR cur_status = 2) THEN
      UPDATE delivery_routes
      SET compliance_status = 3, last_updated_by = rec.driver_id
      WHERE route_id = rec.route_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM delivery_routes ORDER BY route_id;
